/// Small vector math helpers used across the game.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct V2 {
    pub x: f32,
    pub y: f32,
}

impl V2 {
    pub const ZERO: V2 = V2 { x: 0.0, y: 0.0 };

    pub const fn new(x: f32, y: f32) -> Self {
        V2 { x, y }
    }

    pub fn add(self, other: V2) -> V2 {
        V2::new(self.x + other.x, self.y + other.y)
    }

    pub fn sub(self, other: V2) -> V2 {
        V2::new(self.x - other.x, self.y - other.y)
    }

    pub fn scale(self, s: f32) -> V2 {
        V2::new(self.x * s, self.y * s)
    }

    pub fn len(self) -> f32 {
        (self.x * self.x + self.y * self.y).sqrt()
    }

    pub fn norm(self) -> V2 {
        let l = self.len();
        if l > 0.0001 {
            self.scale(1.0 / l)
        } else {
            V2::ZERO
        }
    }

    pub fn lerp(self, other: V2, t: f32) -> V2 {
        V2::new(self.x + (other.x - self.x) * t, self.y + (other.y - self.y) * t)
    }
}

pub fn clamp(v: f32, lo: f32, hi: f32) -> f32 {
    if v < lo {
        lo
    } else if v > hi {
        hi
    } else {
        v
    }
}

pub fn clamp_i(v: i32, lo: i32, hi: i32) -> i32 {
    if v < lo {
        lo
    } else if v > hi {
        hi
    } else {
        v
    }
}

pub fn lerp(a: f32, b: f32, t: f32) -> f32 {
    a + (b - a) * t
}

pub fn smoothstep(t: f32) -> f32 {
    let t = clamp(t, 0.0, 1.0);
    t * t * (3.0 - 2.0 * t)
}

pub fn approach(current: f32, target: f32, delta: f32) -> f32 {
    if current < target {
        (current + delta).min(target)
    } else {
        (current - delta).max(target)
    }
}

pub fn dist(a: V2, b: V2) -> f32 {
    (a.x - b.x).hypot(a.y - b.y)
}

pub fn aabb_overlap(ax: f32, ay: f32, aw: f32, ah: f32, bx: f32, by: f32, bw: f32, bh: f32) -> bool {
    ax < bx + bw && ax + aw > bx && ay < by + bh && ay + ah > by
}

pub fn ease_out(t: f32) -> f32 {
    let t = clamp(t, 0.0, 1.0);
    1.0 - (1.0 - t) * (1.0 - t)
}

/// Deterministic RNG and hashing so worlds can be reproduced from a seed.
#[derive(Clone, Debug)]
pub struct Rng {
    state: u64,
}

impl Rng {
    pub fn new(seed: u32) -> Self {
        let mut s = 0x9E37_79B9_7F4A_7C15u64 ^ (seed as u64).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        if s == 0 {
            s = 0xDEAD_BEEF_CAFE_F00D;
        }
        Rng { state: s }
    }

    pub fn next_u64(&mut self) -> u64 {
        // xorshift64*
        let mut x = self.state;
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        self.state = x;
        x.wrapping_mul(0x2545_F491_4F6C_DD1D)
    }

    pub fn next_u32(&mut self) -> u32 {
        (self.next_u64() >> 32) as u32
    }

    pub fn f32(&mut self) -> f32 {
        (self.next_u32() >> 8) as f32 / 16_777_216.0
    }

    pub fn range(&mut self, lo: f32, hi: f32) -> f32 {
        lo + (hi - lo) * self.f32()
    }

    pub fn range_i(&mut self, lo: i32, hi: i32) -> i32 {
        if hi <= lo {
            return lo;
        }
        lo + (self.next_u32() % ((hi - lo + 1) as u32)) as i32
    }

    pub fn chance(&mut self, p: f32) -> bool {
        self.f32() < p
    }

    pub fn sign(&mut self) -> f32 {
        if self.next_u32() & 1 == 0 {
            -1.0
        } else {
            1.0
        }
    }
}

/// Stable 2D hash used for per-tile decoration. Returns a value in [0, 1).
pub fn hash2(x: i32, y: i32, seed: u32) -> f32 {
    let mut h = (x as u32).wrapping_mul(0x27D4_EB2D)
        ^ (y as u32).wrapping_mul(0x1656_67B1)
        ^ seed.wrapping_mul(0x9E37_79B9);
    h ^= h >> 15;
    h = h.wrapping_mul(0x85EB_CA6B);
    h ^= h >> 13;
    h = h.wrapping_mul(0xC2B2_AE35);
    h ^= h >> 16;
    (h >> 8) as f32 / 16_777_216.0
}

pub fn hash_i(x: i32, y: i32, seed: u32) -> u32 {
    let mut h = (x as u32).wrapping_mul(0x27D4_EB2D)
        ^ (y as u32).wrapping_mul(0x1656_67B1)
        ^ seed.wrapping_mul(0x9E37_79B9);
    h ^= h >> 15;
    h = h.wrapping_mul(0x85EB_CA6B);
    h ^= h >> 13;
    h = h.wrapping_mul(0xC2B2_AE35);
    h ^= h >> 16;
    h
}

/// Cheap 1D value noise with smooth interpolation, used for terrain.
pub fn value_noise(x: f32, seed: u32) -> f32 {
    let i = x.floor() as i32;
    let f = x - x.floor();
    let a = hash2(i, 0, seed);
    let b = hash2(i + 1, 0, seed);
    let t = f * f * (3.0 - 2.0 * f);
    a + (b - a) * t
}

pub fn fbm(x: f32, seed: u32, octaves: u32) -> f32 {
    let mut amp = 0.5;
    let mut freq = 1.0;
    let mut sum = 0.0;
    let mut norm = 0.0;
    for i in 0..octaves {
        sum += value_noise(x * freq, seed.wrapping_add(i * 7919)) * amp;
        norm += amp;
        amp *= 0.5;
        freq *= 2.03;
    }
    sum / norm
}

//! Thin immediate-mode drawing bridge to the browser's Canvas2D context.
//!
//! All rendering calls are batched by the browser. Keeping the bridge tiny
//! makes it easy to run the same simulation natively in unit tests.

use crate::math::V2;

#[inline]
pub const fn rgba(r: u8, g: u8, b: u8, a: u8) -> u32 {
    ((r as u32) << 24) | ((g as u32) << 16) | ((b as u32) << 8) | (a as u32)
}

#[inline]
pub const fn rgb(r: u8, g: u8, b: u8) -> u32 {
    rgba(r, g, b, 255)
}

#[inline]
pub fn alpha(color: u32, a: u8) -> u32 {
    (color & 0xFFFF_FF00) | (a as u32)
}

#[inline]
pub fn mix(a: u32, b: u32, t: f32) -> u32 {
    let t = crate::math::clamp(t, 0.0, 1.0);
    let ar = (a >> 24) as f32;
    let ag = ((a >> 16) & 255) as f32;
    let ab = ((a >> 8) & 255) as f32;
    let aa = (a & 255) as f32;
    let br = (b >> 24) as f32;
    let bg = ((b >> 16) & 255) as f32;
    let bb = ((b >> 8) & 255) as f32;
    let ba = (b & 255) as f32;
    rgba(
        (ar + (br - ar) * t) as u8,
        (ag + (bg - ag) * t) as u8,
        (ab + (bb - ab) * t) as u8,
        (aa + (ba - aa) * t) as u8,
    )
}

#[inline]
pub fn with_light(color: u32, light: f32) -> u32 {
    let l = 0.35 + 0.65 * light;
    let r = (((color >> 24) & 255) as f32 * l) as u8;
    let g = (((color >> 16) & 255) as f32 * l) as u8;
    let b = (((color >> 8) & 255) as f32 * l) as u8;
    let a = (color & 255) as u8;
    rgba(r, g, b, a)
}

