#[derive(Clone)]
pub struct World {
    pub tiles: Vec<u8>,
    pub walls: Vec<u8>,
    pub surface: Vec<i32>,
    pub sky_top: Vec<i32>,
    pub biome: Vec<u8>,
    pub seed: u32,
    pub spawn: V2,
    pub modified: Vec<(i32, i32, u8)>,
    pub minimap: Vec<u8>,
    pub map_dirty: bool,
}

impl World {
    #[inline]
    pub fn idx(x: i32, y: i32) -> usize {
        (y * W + x) as usize
    }

    #[inline]
    pub fn in_bounds(x: i32, y: i32) -> bool {
        x >= 0 && y >= 0 && x < W && y < H
    }

    #[inline]
    pub fn get(&self, x: i32, y: i32) -> u8 {
        if Self::in_bounds(x, y) {
            self.tiles[Self::idx(x, y)]
        } else if y >= H {
            BEDROCK
        } else {
            AIR
        }
    }

    #[inline]
    pub fn get_wall(&self, x: i32, y: i32) -> u8 {
        if Self::in_bounds(x, y) {
            self.walls[Self::idx(x, y)]
        } else {
            WALL_NONE
        }
    }

    #[inline]
    pub fn solid(&self, x: i32, y: i32) -> bool {
        is_solid(self.get(x, y))
    }

    #[inline]
    pub fn platform(&self, x: i32, y: i32) -> bool {
        self.get(x, y) == PLATFORM
    }

    #[inline]
    pub fn water(&self, x: i32, y: i32) -> bool {
        self.get(x, y) == WATER
    }

    #[inline]
    pub fn solid_px(&self, px: f32, py: f32) -> bool {
        self.solid((px / TILE as f32).floor() as i32, (py / TILE as f32).floor() as i32)
    }

    #[inline]
    pub fn water_px(&self, px: f32, py: f32) -> bool {
        self.water((px / TILE as f32).floor() as i32, (py / TILE as f32).floor() as i32)
    }

    /// Records a player-made alteration and keeps derived caches fresh.
    pub fn set_tile(&mut self, x: i32, y: i32, t: u8) -> bool {
        if !Self::in_bounds(x, y) {
            return false;
        }
        let i = Self::idx(x, y);
        if self.tiles[i] == t {
            return false;
        }
        self.tiles[i] = t;
        self.modified.push((x, y, t));
        self.recompute_sky(x);
        self.update_map(x, y);
        self.map_dirty = true;
        true
    }

    pub fn set_wall(&mut self, x: i32, y: i32, w: u8) {
        if Self::in_bounds(x, y) {
            self.walls[Self::idx(x, y)] = w;
            self.update_map(x, y);
        }
    }

    pub fn recompute_sky(&mut self, x: i32) {
        if x < 0 || x >= W {
            return;
        }
        let mut top = H;
        for y in 0..H {
            let t = self.tiles[Self::idx(x, y)];
            if is_solid(t) || t == WATER {
                top = y;
                break;
            }
        }
        self.sky_top[x as usize] = top;
    }

    pub fn surface_px(&self, x: i32) -> f32 {
        self.surface[clamp_i(x, 0, W - 1) as usize] as f32 * TILE as f32
    }

    fn update_map(&mut self, x: i32, y: i32) {
        if !Self::in_bounds(x, y) {
            return;
        }
        let (r, g, b) = self.map_pixel_color(x, y);
        let i = ((y * W + x) * 4) as usize;
        self.minimap[i] = r;
        self.minimap[i + 1] = g;
        self.minimap[i + 2] = b;
        self.minimap[i + 3] = 255;
    }

    fn map_pixel_color(&self, x: i32, y: i32) -> (u8, u8, u8) {
        let t = self.get(x, y);
        let w = self.get_wall(x, y);
        let n = hash2(x, y, self.seed) * 14.0 - 7.0;
        if t != AIR && t != WATER {
            let (r, g, b) = tile_map_color(t);
            return (
                (r as f32 + n).clamp(0.0, 255.0) as u8,
                (g as f32 + n).clamp(0.0, 255.0) as u8,
                (b as f32 + n).clamp(0.0, 255.0) as u8,
            );
        }
        if w != WALL_NONE {
            let (r, g, b) = match w {
                WALL_DIRT => (74, 52, 36),
                WALL_STONE => (56, 58, 66),
                WALL_WOOD => (76, 54, 34),
                _ => (40, 40, 48),
            };
            return (
                (r as f32 + n).clamp(0.0, 255.0) as u8,
                (g as f32 + n).clamp(0.0, 255.0) as u8,
                (b as f32 + n).clamp(0.0, 255.0) as u8,
            );
        }
        if t == WATER {
            return (48, 112, 182);
        }
        // Sky: brighter at the surface, fading into the deep.
        let depth = (y as f32 / self.surface[x as usize].max(1) as f32).clamp(0.0, 1.0);
        if y < self.surface[x as usize] {
            let r = 88.0 - depth * 40.0;
            let g = 154.0 - depth * 80.0;
            let b = 218.0 - depth * 70.0;
            (r as u8, g as u8, b as u8)
        } else {
            (14, 18, 30)
        }
    }

    pub fn rebuild_minimap(&mut self) {
        for y in 0..H {
            for x in 0..W {
                self.update_map(x, y);
            }
        }
    }

    /// True if the tile at this position can support the player from above.
    pub fn solid_or_platform(&self, x: i32, y: i32) -> bool {
        let t = self.get(x, y);
        is_solid(t) || is_platform(t)
    }

    pub fn bench_near(&self, px: f32, py: f32, radius: i32) -> bool {
        let cx = (px / TILE as f32) as i32;
        let cy = (py / TILE as f32) as i32;
        for y in (cy - radius)..=(cy + radius) {
            for x in (cx - radius)..=(cx + radius) {
                if self.get(x, y) == BENCH {
                    return true;
                }
            }
        }
        false
    }

    pub fn count_near(&self, px: f32, py: f32, radius: i32, tile: u8) -> i32 {
        let cx = (px / TILE as f32) as i32;
        let cy = (py / TILE as f32) as i32;
        let mut n = 0;
        for y in (cy - radius)..=(cy + radius) {
            for x in (cx - radius)..=(cx + radius) {
                if self.get(x, y) == tile {
                    n += 1;
                }
            }
        }
        n
    }
}

// ---------------------------------------------------------------------------
// Generation
// ---------------------------------------------------------------------------

pub fn generate(seed: u32) -> World {
    let mut rng = Rng::new(seed);
    let mut tiles = vec![AIR; (W * H) as usize];
    let mut walls = vec![WALL_NONE; (W * H) as usize];
    let mut surface = vec![(H as f32 * 0.32) as i32; W as usize];
    let mut biome = vec![BIOME_FOREST; W as usize];

    let desert_center = W * 68 / 100;
    let snow_center = W * 20 / 100;

    // Terrain height and biome assignment.
    for x in 0..W {
        let base = H as f32 * 0.30;
        let broad = (fbm(x as f32 * 0.0052, seed, 4) - 0.5) * 44.0;
        let detail = (fbm(x as f32 * 0.021, seed ^ 0x51ed, 3) - 0.5) * 11.0;
        let ridge = ((x as f32) * 0.017).sin() * 4.0;
        let mut h = (base + broad + detail + ridge).round() as i32;
        h = clamp_i(h, 42, (H as f32 * 0.52) as i32);

        let b = if (x - desert_center).abs() < 52 {
            BIOME_DESERT
        } else if (x - snow_center).abs() < 40 {
            BIOME_SNOW
        } else if x < 34 || x > W - 34 {
            BIOME_SNOW
        } else {
            BIOME_FOREST
        };
        biome[x as usize] = b;
        surface[x as usize] = h;

        let top_tile = match b {
            BIOME_DESERT => SAND,
            BIOME_SNOW => SNOW,
            _ => GRASS,
        };
        let filler = match b {
            BIOME_DESERT => SAND,
            BIOME_SNOW => SNOW,
            _ => DIRT,
        };
        let dirt_depth = 9 + (fbm(x as f32 * 0.13, seed ^ 0x77aa, 2) * 8.0) as i32;

        for y in h..H {
            let t = if y == h {
                top_tile
            } else if y <= h + dirt_depth {
                if b == BIOME_FOREST && y > h + 4 && hash2(x, y, seed ^ 0x9911) > 0.86 {
                    CLAY
                } else {
                    filler
                }
            } else {
                STONE
            };
            tiles[World::idx(x, y)] = t;
        }

        // Background walls.
        for y in h..H {
            let depth = y - h;
            let w = if depth < 4 {
                WALL_NONE
            } else if depth < dirt_depth + 6 {
                WALL_DIRT
            } else {
                WALL_STONE
            };
            walls[World::idx(x, y)] = w;
        }
    }

    // Deep dirt pockets and stone variation.
    for x in 0..W {
        for y in surface[x as usize]..H {
            if tiles[World::idx(x, y)] != STONE {
                continue;
            }
            let n = fbm(x as f32 * 0.055 + y as f32 * 0.033, seed ^ 0xa53, 3);
            if n > 0.68 && hash2(x, y, seed ^ 0x441) > 0.45 {
                tiles[World::idx(x, y)] = DIRT;
            }
        }
    }

    // Carve caves with wandering worms.
    let mut worms = 58;
    while worms > 0 {
        worms -= 1;
        let mut x = rng.range_i(10, W - 10) as f32;
        let mut y = rng.range_i(0, H - 30) as f32;
        let surf = surface[x as usize] as f32;
        if y < surf + 5.0 {
            y = surf + 5.0 + rng.range(0.0, 40.0);
        }
        let mut angle = rng.range(0.0, std::f32::consts::TAU);
        let steps = rng.range_i(60, 230);
        let base_r = rng.range(0.9, 2.4);
        for i in 0..steps {
            let r = base_r + ((i as f32 / steps as f32) * std::f32::consts::PI).sin() * rng.range(0.0, 1.4);
            carve_circle(&mut tiles, &mut walls, x, y, r, seed);
            angle += rng.range(-0.32, 0.32);
            x += angle.cos() * 1.35;
            y += angle.sin() * 1.35;
            if x < 8.0 || x > (W - 8) as f32 || y > (H - 8) as f32 {
                break;
            }
        }
    }

    // A handful of larger caverns deep down.
    for _ in 0..16 {
        let cx = rng.range_i(20, W - 20) as f32;
        let cy = rng.range_i((H as f32 * 0.55) as i32, H - 22) as f32;
        let rx = rng.range(5.0, 15.0);
        let ry = rng.range(3.0, 8.0);
        for y in (cy - ry - 2.0) as i32..=(cy + ry + 2.0) as i32 {
            for x in (cx - rx - 2.0) as i32..=(cx + rx + 2.0) as i32 {
                if !World::in_bounds(x, y) {
                    continue;
                }
                let dx = (x as f32 - cx) / rx;
                let dy = (y as f32 - cy) / ry;
                if dx * dx + dy * dy <= 1.0 {
                    let i = World::idx(x, y);
                    if is_solid(tiles[i]) || tiles[i] == AIR {
                        tiles[i] = AIR;
                        if walls[i] == WALL_NONE {
                            walls[i] = WALL_STONE;
                        }
                    }
                }
            }
        }
    }

    // Ore veins.
    let mut place_vein = |tiles: &mut Vec<u8>, rng: &mut Rng, tile: u8, y0: i32, y1: i32, count: i32, size: f32| {
        for _ in 0..count {
            let cx = rng.range_i(6, W - 6);
            let cy = rng.range_i(y0.clamp(0, H - 2), y1.clamp(1, H - 2));
            let approx = rng.range_i(2, size as i32);
            for oy in -approx..=approx {
                for ox in -approx..=approx {
                    let x = cx + ox;
                    let y = cy + oy;
                    if !World::in_bounds(x, y) {
                        continue;
                    }
                    let d = (ox * ox + oy * oy) as f32;
                    if d > (approx * approx) as f32 {
                        continue;
                    }
                    let i = World::idx(x, y);
                    if tiles[i] == STONE && hash2(x, y, seed) > 0.25 {
                        tiles[i] = tile;
                    }
                }
            }
        }
    };
    place_vein(&mut tiles, &mut rng, COPPER, (H as f32 * 0.36) as i32, (H as f32 * 0.70) as i32, 74, 5.0);
    place_vein(&mut tiles, &mut rng, IRON, (H as f32 * 0.46) as i32, (H as f32 * 0.86) as i32, 62, 4.5);
    place_vein(&mut tiles, &mut rng, GOLD, (H as f32 * 0.66) as i32, H - 12, 40, 3.8);
    place_vein(&mut tiles, &mut rng, GEM, (H as f32 * 0.78) as i32, H - 8, 22, 3.0);

    // Surface ponds in forest and snow.
    for _ in 0..5 {
        let cx = rng.range_i(50, W - 50);
        if (cx - W / 2).abs() < 16 {
            continue;
        }
        if biome[cx as usize] == BIOME_DESERT {
            continue;
        }
        let half = rng.range_i(4, 9);
        let depth = rng.range_i(2, 4);
        let ground = surface[cx as usize];
        for dx in -half..=half {
            let x = cx + dx;
            if x < 2 || x >= W - 2 {
                continue;
            }
            let fall = ((half - dx.abs()) as f32 / half as f32 * depth as f32).round() as i32;
            for d in 0..=fall {
                let y = ground + d;
                if World::in_bounds(x, y) {
                    let i = World::idx(x, y);
                    if d == fall {
                        tiles[i] = if biome[x as usize] == BIOME_FOREST { CLAY } else { SNOW };
                    } else {
                        tiles[i] = WATER;
                    }
                }
            }
            surface[x as usize] = ground + fall;
            // Restore dirt below the pond bottom.
            let by = ground + fall + 1;
            for yy in by..(by + 4).min(H) {
                let i = World::idx(x, yy);
                if tiles[i] == AIR {
                    tiles[i] = STONE;
                }
            }
        }
        // Keep water from spilling at the edges by adding a lip.
        for dx in [-(half + 1), half + 1] {
            let x = cx + dx;
            if x >= 0 && x < W {
                let y = ground;
                if World::in_bounds(x, y) {
                    let i = World::idx(x, y);
                    if tiles[i] == AIR {
                        tiles[i] = DIRT;
                    }
                }
            }
        }
    }

    // Trees, cacti and giant mushrooms.
    let mut x = 6;
    while x < W - 6 {
        let b = biome[x as usize];
        let ground = surface[x as usize];
        let top = get_t(tiles.as_slice(), x, ground);
        let above_clear = get_t(tiles.as_slice(), x, ground - 1) == AIR && get_t(tiles.as_slice(), x, ground - 2) == AIR;
        if above_clear && ((b == BIOME_FOREST && top == GRASS) || (b == BIOME_SNOW && top == SNOW)) {
            if rng.chance(if b == BIOME_FOREST { 0.34 } else { 0.22 }) {
                grow_tree(&mut tiles, &mut walls, x, ground, seed, &mut rng, b);
                x += rng.range_i(3, 7);
                continue;
            }
        } else if b == BIOME_DESERT && top == SAND && above_clear && rng.chance(0.10) {
            let h = rng.range_i(2, 5);
            for i in 1..=h {
                let y = ground - i;
                if World::in_bounds(x, y) && get_t(tiles.as_slice(), x, y) == AIR {
                    set_t(&mut tiles, x, y, CACTUS);
                }
            }
            x += rng.range_i(3, 6);
            continue;
        }
        x += 1;
    }

    // Glow mushrooms in caves.
    for _ in 0..260 {
        let x = rng.range_i(4, W - 4);
        let y = rng.range_i((surface[x as usize] + 6).min(H - 4), H - 4);
        if get_t(tiles.as_slice(), x, y) == AIR
            && !is_solid(get_t(tiles.as_slice(), x, y + 1))
            && is_solid(get_t(tiles.as_slice(), x, y + 2))
            && walls[World::idx(x, y)] != WALL_NONE
        {
            set_t(&mut tiles, x, y, MUSHROOM);
        }
    }

    // Small abandoned cabins with a torch and workbench.
    for _ in 0..4 {
        let x = rng.range_i(50, W - 50);
        let y = rng.range_i((H as f32 * 0.55) as i32, H - 16);
        build_cabin(&mut tiles, &mut walls, x, y, &mut rng);
    }

    // Bedrock floor.
    for x in 0..W {
        let jag = (hash2(x, 0, seed) * 4.0) as i32;
        for y in (H - 4 - jag)..H {
            if World::in_bounds(x, y) {
                let i = World::idx(x, y);
                tiles[i] = BEDROCK;
                walls[i] = WALL_NONE;
            }
        }
    }

    // Recompute the surface cache after caves/ponds and find a spawn point.
    for x in 0..W {
        let mut top = H;
        for y in 0..H {
            let t = tiles[World::idx(x, y)];
            if is_solid(t) || t == WATER {
                top = y;
                break;
            }
        }
        surface[x as usize] = top;
    }

    let mut spawn_x = W / 2;
    let mut best = i32::MAX;
    for x in (W / 2 - 60)..(W / 2 + 60) {
        let b = biome[x as usize];
        let top = surface[x as usize];
        if b == BIOME_FOREST && top < H - 20 {
            let left = surface[(x - 1) as usize];
            let right = surface[(x + 1) as usize];
            let flatness = (left - top).abs() + (right - top).abs();
            if flatness < best {
                best = flatness;
                spawn_x = x;
            }
        }
    }
    if best == i32::MAX {
        spawn_x = W / 2;
    }
    let ground_y = surface[spawn_x as usize];
    let mut spawn = V2::new(spawn_x as f32 * TILE as f32 + TILE as f32 * 0.5, (ground_y as f32 - 2.2) * TILE as f32);

    // Ensure there is a solid pad under the spawn.
    for yy in ground_y..(ground_y + 3).min(H) {
        let i = World::idx(spawn_x, yy);
        if !is_solid(tiles[i]) {
            tiles[i] = DIRT;
        }
    }
    if get_t(tiles.as_slice(), spawn_x, ground_y - 1) != AIR {
        let i = World::idx(spawn_x, ground_y - 1);
        tiles[i] = AIR;
    }
    spawn.y = (ground_y as f32 - 2.0) * TILE as f32;

    let mut sky_top = vec![H; W as usize];
    for x in 0..W {
        let mut top = H;
        for y in 0..H {
            let t = tiles[World::idx(x, y)];
            if is_solid(t) || t == WATER {
                top = y;
                break;
            }
        }
        sky_top[x as usize] = top;
        surface[x as usize] = top;
    }

    let mut world = World {
        tiles,
        walls,
        surface,
        sky_top,
        biome,
        seed,
        spawn,
        modified: Vec::new(),
        minimap: vec![0; (W * H * 4) as usize],
        map_dirty: true,
    };
    world.rebuild_minimap();
    world
}

fn get_t(tiles: &[u8], x: i32, y: i32) -> u8 {
    if World::in_bounds(x, y) {
        tiles[World::idx(x, y)]
    } else {
        AIR
    }
}

fn set_t(tiles: &mut [u8], x: i32, y: i32, t: u8) {
    if World::in_bounds(x, y) {
        tiles[World::idx(x, y)] = t;
    }
}

fn carve_circle(tiles: &mut [u8], walls: &mut [u8], cx: f32, cy: f32, r: f32, seed: u32) {
    let x0 = (cx - r - 1.0) as i32;
    let x1 = (cx + r + 1.0) as i32;
    let y0 = (cy - r - 1.0) as i32;
    let y1 = (cy + r + 1.0) as i32;
    for y in y0..=y1 {
        for x in x0..=x1 {
            if !World::in_bounds(x, y) {
                continue;
            }
            let d = ((x as f32 - cx).powi(2) + (y as f32 - cy).powi(2)).sqrt();
            if d <= r {
                let i = World::idx(x, y);
                if is_solid(tiles[i]) {
                    if walls[i] == WALL_NONE {
                        walls[i] = if y > (H / 2) { WALL_STONE } else { WALL_DIRT };
                    }
                    tiles[i] = AIR;
                } else if tiles[i] == AIR {
                    // Keep background walls behind natural caverns.
                    if walls[i] == WALL_NONE && y > 8 {
                        walls[i] = if y > (H / 2) { WALL_STONE } else { WALL_DIRT };
                    }
                }
            }
            // Rough the rim a little.
            if d > r && d <= r + 0.75 && hash2(x, y, seed) > 0.82 {
                let i = World::idx(x, y);
                if is_solid(tiles[i]) {
                    tiles[i] = AIR;
                }
            }
        }
    }
}

fn grow_tree(tiles: &mut [u8], walls: &mut [u8], x: i32, ground: i32, seed: u32, rng: &mut Rng, biome: u8) {
    let height = rng.range_i(5, 11);
    let pine = biome == BIOME_SNOW;
    for i in 1..=height {
        let y = ground - i;
        if !World::in_bounds(x, y) {
            return;
        }
        set_t(tiles, x, y, WOOD);
    }
    let top = ground - height;
    if pine {
        for layer in 0..4 {
            let y = top - layer;
            let r = 2 + (3 - layer) as i32;
            for dx in -r..=r {
                for dy in -1..=1 {
                    if dx.abs() + dy.abs() * 2 <= r + 1 {
                        let tx = x + dx;
                        let ty = y + dy;
                        if World::in_bounds(tx, ty) && get_t(tiles, tx, ty) == AIR {
                            set_t(tiles, tx, ty, LEAVES);
                        }
                    }
                }
            }
        }
        set_t(tiles, x, top - 4, LEAVES);
        set_t(tiles, x, top - 5, LEAVES);
    } else {
        let r = rng.range_i(2, 4);
        for dy in -r..=r {
            for dx in -r..=r {
                let d = (dx * dx + dy * dy) as f32;
                if d <= (r * r) as f32 + 1.0 && hash2(x + dx, top + dy, seed ^ 0x77) > 0.18 {
                    let tx = x + dx;
                    let ty = top + dy - 1;
                    if World::in_bounds(tx, ty) && get_t(tiles, tx, ty) == AIR {
                        set_t(tiles, tx, ty, LEAVES);
                    }
                }
            }
        }
        // A couple of branches.
        for side in [-1, 1] {
            if rng.chance(0.7) {
                let by = ground - height / 2;
                for step in 1..=2 {
                    set_t(tiles, x + side * step, by - step + 1, WOOD);
                }
            }
        }
    }
    // Roots / dirt collar.
    for dx in -1..=1 {
        let wx = x + dx;
        let wy = ground;
        if World::in_bounds(wx, wy) && get_t(tiles, wx, wy) == AIR {
            // no-op, keeps trunks on the ground
        }
    }
    let _ = walls;
}

fn build_cabin(tiles: &mut [u8], walls: &mut [u8], cx: i32, cy: i32, rng: &mut Rng) {
    let w = rng.range_i(7, 10);
    let h = rng.range_i(5, 6);
    let x0 = cx - w / 2;
    let y0 = cy - h;
    // Clear and build walls.
    for y in y0..=(cy + 1) {
        for x in x0..=(x0 + w) {
            if !World::in_bounds(x, y) {
                continue;
            }
            let i = World::idx(x, y);
            tiles[i] = AIR;
            walls[i] = WALL_WOOD;
        }
    }
    // Floor.
    for x in x0..=(x0 + w) {
        let y = cy + 1;
        if World::in_bounds(x, y) {
            let i = World::idx(x, y);
            if !is_solid(tiles[i]) {
                tiles[i] = WOOD;
            }
        }
    }
    // Side pillars.
    for y in y0..=cy {
        for x in [x0, x0 + w] {
            if World::in_bounds(x, y) {
                let i = World::idx(x, y);
                tiles[i] = WOOD;
            }
        }
    }
    // Roof.
    for x in x0..=(x0 + w) {
        if World::in_bounds(x, y0 - 1) {
            let i = World::idx(x, y0 - 1);
            tiles[i] = WOOD;
        }
    }
    // Doorway gaps.
    for y in (cy - 2)..=cy {
        let i = World::idx(x0, y);
        if y >= cy - 1 {
            let idx = World::idx(x0, y);
            if World::in_bounds(x0, y) {
                tiles[idx] = AIR;
                let _ = i;
            }
        }
    }
    // Furniture.
    if World::in_bounds(x0 + 2, cy) {
        let i = World::idx(x0 + 2, cy);
        if tiles[i] == AIR {
            tiles[i] = BENCH;
        }
    }
    if World::in_bounds(x0 + w - 2, cy - 3) {
        let i = World::idx(x0 + w - 2, cy - 3);
        if tiles[i] == AIR {
            tiles[i] = TORCH;
        }
    }
    let _ = rng;
}

// ---------------------------------------------------------------------------
// Headless tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn world_generates_with_spawn_support() {
        let w = generate(12345);
        let sx = (w.spawn.x / TILE as f32) as i32;
        let sy = (w.spawn.y / TILE as f32) as i32;
        assert!(World::in_bounds(sx, sy));
        let mut found = false;
        for y in (sy + 1)..(sy + 5) {
            if w.solid(sx, y) {
                found = true;
            }
        }
        assert!(found, "spawn must have ground below");
        assert!(w.solid(sx, sy + 3));
    }

    #[test]
    fn world_has_ores_and_trees() {
        let w = generate(777);
        let mut ores = 0;
        let mut trees = 0;
        let mut water = 0;
        for t in &w.tiles {
            if matches!(*t, COPPER | IRON | GOLD | GEM) {
                ores += 1;
            }
            if *t == WOOD {
                trees += 1;
            }
            if *t == WATER {
                water += 1;
            }
        }
        assert!(ores > 500, "ores: {ores}");
        assert!(trees > 100, "trees: {trees}");
        assert!(water > 0);
    }

    #[test]
    fn tile_set_updates_cache_and_surface() {
        let mut w = generate(5);
        let x = 100;
        let top = w.surface[x as usize];
        assert!(w.solid(x, top));
        w.set_tile(x, top, AIR);
        assert!(!w.solid(x, top));
        assert!(w.sky_top[x as usize] != top || w.solid(x, top));
        w.set_tile(x, top, STONE);
        assert!(w.solid(x, top));
    }

    #[test]
    fn hardness_ordering() {
        assert!(hardness(DIRT) < hardness(STONE));
        assert!(hardness(STONE) < hardness(GOLD));
        assert!(hardness(BEDROCK) > 1000.0);
    }
}

//! Input state, normalized between keyboard, mouse and touch.

use crate::math::V2;

pub const KEY_A: usize = 0;
pub const KEY_D: usize = 1;
pub const KEY_S: usize = 2;
pub const KEY_W: usize = 3;
pub const KEY_SPACE: usize = 4;
pub const KEY_SHIFT: usize = 5;
pub const KEY_E: usize = 6;
pub const KEY_C: usize = 7;
pub const KEY_M: usize = 8;
pub const KEY_ESC: usize = 9;
pub const KEY_DIGIT_1: usize = 10;
pub const KEY_DIGIT_0: usize = 19;
pub const KEY_N: usize = 20;
pub const KEY_ENTER: usize = 21;
pub const KEY_LEFT: usize = 22;
pub const KEY_RIGHT: usize = 23;
pub const KEY_UP: usize = 24;
pub const KEY_DOWN: usize = 25;
pub const KEY_COUNT: usize = 26;

#[derive(Clone, Debug)]
pub struct Input {
    pub keys: [bool; KEY_COUNT],
    pub pressed: [bool; KEY_COUNT],
    pub mouse: V2,
    pub mouse_down: bool,
    pub mouse_pressed: bool,
    pub mouse_released: bool,
    pub right_down: bool,
    pub right_pressed: bool,
    pub right_released: bool,
    pub wheel: f32,
    pub touch_mode: bool,
    pub touches: Vec<Touch>,
    pub any_input: bool,
}

#[derive(Clone, Copy, Debug, Default)]
pub struct Touch {
    pub id: u32,
    pub pos: V2,
    pub active: bool,
}

impl Default for Input {
    fn default() -> Self {
        Self::new()
    }
}

impl Input {
    pub fn new() -> Self {
        Input {
            keys: [false; KEY_COUNT],
            pressed: [false; KEY_COUNT],
            mouse: V2::new(-100.0, -100.0),
            mouse_down: false,
            mouse_pressed: false,
            mouse_released: false,
            right_down: false,
            right_pressed: false,
            right_released: false,
            wheel: 0.0,
            touch_mode: false,
            touches: Vec::new(),
            any_input: false,
        }
    }

    pub fn end_frame(&mut self) {
        self.pressed = [false; KEY_COUNT];
        self.mouse_pressed = false;
        self.mouse_released = false;
        self.right_pressed = false;
        self.right_released = false;
        self.wheel = 0.0;
        self.any_input = false;
    }

    pub fn key(&self, k: usize) -> bool {
        self.keys.get(k).copied().unwrap_or(false)
    }

    pub fn press(&self, k: usize) -> bool {
        self.pressed.get(k).copied().unwrap_or(false)
    }

    pub fn left(&self) -> bool {
        self.key(KEY_A) || self.key(KEY_LEFT)
    }

    pub fn right(&self) -> bool {
        self.key(KEY_D) || self.key(KEY_RIGHT)
    }

    pub fn up(&self) -> bool {
        self.key(KEY_W) || self.key(KEY_UP)
    }

    pub fn down(&self) -> bool {
        self.key(KEY_S) || self.key(KEY_DOWN)
    }

    pub fn jump_held(&self) -> bool {
        self.key(KEY_SPACE) || self.key(KEY_W) || self.key(KEY_UP)
    }

    pub fn jump_pressed(&self) -> bool {
        self.press(KEY_SPACE) || self.press(KEY_W) || self.press(KEY_UP)
    }

    pub fn down_pressed(&self) -> bool {
        self.press(KEY_S) || self.press(KEY_DOWN)
    }
}

//! Player state, movement and tile collision.

use crate::input::Input;
use crate::math::{approach, clamp, V2};
use crate::world::{World, TILE};

pub const PLAYER_W: f32 = 11.0;
pub const PLAYER_H: f32 = 27.0;

#[derive(Clone, Debug)]
pub struct Player {
    pub pos: V2,
    pub vel: V2,
    pub width: f32,
    pub height: f32,
    pub on_ground: bool,
    pub facing: f32,
    pub hp: f32,
    pub max_hp: f32,
    pub invuln: f32,
    pub hurt_flash: f32,
    pub walk_phase: f32,
    pub coyote: f32,
    pub jump_buffer: f32,
    pub in_water: f32,
    pub swim_phase: f32,
    pub use_anim: f32,
    pub use_item: u8,
    pub attack_cooldown: f32,
    pub potion_cooldown: f32,
    pub respawn: V2,
    pub dead: bool,
    pub death_timer: f32,
    pub moving: f32,
    pub fall_speed: f32,
}

impl Player {
    pub fn new(spawn: V2) -> Self {
        Player {
            pos: spawn,
            vel: V2::ZERO,
            width: PLAYER_W,
            height: PLAYER_H,
            on_ground: false,
            facing: 1.0,
            hp: 100.0,
            max_hp: 100.0,
            invuln: 0.0,
            hurt_flash: 0.0,
            walk_phase: 0.0,
            coyote: 0.0,
            jump_buffer: 0.0,
            in_water: 0.0,
            swim_phase: 0.0,
            use_anim: 0.0,
            use_item: 0,
            attack_cooldown: 0.0,
            potion_cooldown: 0.0,
            respawn: spawn,
            dead: false,
            death_timer: 0.0,
            moving: 0.0,
            fall_speed: 0.0,
        }
    }

    pub fn center(&self) -> V2 {
        V2::new(self.pos.x + self.width * 0.5, self.pos.y + self.height * 0.5)
    }

    pub fn feet(&self) -> V2 {
        V2::new(self.pos.x + self.width * 0.5, self.pos.y + self.height)
    }

    pub fn aabb(&self) -> (f32, f32, f32, f32) {
        (self.pos.x, self.pos.y, self.width, self.height)
    }

    pub fn respawn(&mut self) {
        self.pos = self.respawn;
        self.vel = V2::ZERO;
        self.hp = self.max_hp;
        self.dead = false;
        self.death_timer = 0.0;
        self.invuln = 2.0;
        self.in_water = 0.0;
    }

    pub fn hurt(&mut self, amount: f32, from_x: f32) -> bool {
        if self.invuln > 0.0 || self.dead {
            return false;
        }
        self.hp -= amount;
        self.invuln = 0.65;
        self.hurt_flash = 0.4;
        let dir = if self.center().x < from_x { -1.0 } else { 1.0 };
        self.vel.x = dir * 165.0;
        self.vel.y = -175.0;
        if self.hp <= 0.0 {
            self.hp = 0.0;
            self.dead = true;
            self.death_timer = 0.0;
        }
        true
    }

    pub fn heal(&mut self, amount: f32) -> bool {
        if self.hp >= self.max_hp {
            return false;
        }
        self.hp = (self.hp + amount).min(self.max_hp);
        true
    }

    pub fn update(&mut self, world: &World, input: &Input, dt: f32) -> bool {
        let mut jumped = false;
        if self.dead {
            self.death_timer += dt;
            self.vel.y = (self.vel.y + 1100.0 * dt).min(700.0);
            self.pos = self.pos.add(self.vel.scale(dt));
            return false;
        }

        self.invuln = (self.invuln - dt).max(0.0);
        self.hurt_flash = (self.hurt_flash - dt).max(0.0);
        self.attack_cooldown = (self.attack_cooldown - dt).max(0.0);
        self.potion_cooldown = (self.potion_cooldown - dt).max(0.0);
        self.use_anim = (self.use_anim - dt * 5.5).max(0.0);
        self.coyote = (self.coyote - dt).max(0.0);
        self.jump_buffer = (self.jump_buffer - dt).max(0.0);

        let feet = self.feet();
        let water = world.water_px(feet.x, feet.y - 2.0) || world.water_px(self.center().x, self.center().y);
        if water {
            self.in_water = (self.in_water + dt).min(4.0);
        } else {
            self.in_water = (self.in_water - dt * 3.0).max(0.0);
        }
        let swimming = self.in_water > 0.05;

        if input.jump_pressed() {
            self.jump_buffer = 0.14;
        }

        let mut dir = 0.0;
        if input.left() {
            dir -= 1.0;
        }
        if input.right() {
            dir += 1.0;
        }
        if dir != 0.0 {
            self.facing = dir;
        }

        let max_speed = if swimming { 92.0 } else { 154.0 };
        let accel = if self.on_ground {
            1250.0
        } else if swimming {
            500.0
        } else {
            760.0
        };
        if dir != 0.0 {
            self.vel.x = approach(self.vel.x, dir * max_speed, accel * dt);
            self.walk_phase += dt * (if self.on_ground { 9.5 } else { 3.5 });
            self.moving = 1.0;
        } else {
            let friction = if self.on_ground { 1500.0 } else if swimming { 420.0 } else { 260.0 };
            self.vel.x = approach(self.vel.x, 0.0, friction * dt);
            self.moving = 0.0;
        }

        if swimming {
            self.vel.y += 220.0 * dt;
            self.vel.y = self.vel.y.min(105.0);
            if input.jump_held() {
                self.vel.y -= 520.0 * dt;
                self.vel.y = self.vel.y.max(-125.0);
                self.swim_phase += dt * 9.0;
                self.walk_phase += dt * 5.0;
            }
            if input.down() {
                self.vel.y += 220.0 * dt;
            }
            self.vel.y *= 1.0 - 1.6 * dt;
        } else {
            self.vel.y += 1420.0 * dt;
            self.vel.y = self.vel.y.min(780.0);
            if self.jump_buffer > 0.0 && (self.on_ground || self.coyote > 0.0) {
                self.vel.y = -392.0;
                self.on_ground = false;
                self.coyote = 0.0;
                self.jump_buffer = 0.0;
                jumped = true;
            }
            // Variable jump height.
            if !input.jump_held() && self.vel.y < -140.0 {
                self.vel.y += 1500.0 * dt;
            }
        }

        if self.on_ground {
            self.coyote = 0.1;
        }
        self.fall_speed = self.vel.y;

        let was_ground = self.on_ground;
        self.pos.x += self.vel.x * dt;
        self.resolve_x(world);
        self.pos.y += self.vel.y * dt;
        self.resolve_y(world);
        if self.on_ground && !was_ground && self.fall_speed > 420.0 {
            // landing handled by game for particles
        }
        if self.pos.y > (crate::world::H as f32 * TILE as f32) + 200.0 {
            self.hp = 0.0;
            self.dead = true;
        }
        self.pos.x = clamp(self.pos.x, 1.0, (crate::world::W as f32 * TILE as f32) - self.width - 1.0);
        jumped
    }

    fn resolve_x(&mut self, world: &World) {
        let x0 = (self.pos.x / TILE as f32).floor() as i32;
        let x1 = ((self.pos.x + self.width) / TILE as f32).floor() as i32;
        let y0 = (self.pos.y / TILE as f32).floor() as i32;
        let y1 = ((self.pos.y + self.height - 0.01) / TILE as f32).floor() as i32;
        for y in y0..=y1 {
            for x in x0..=x1 {
                if world.solid(x, y) {
                    if self.vel.x > 0.0 {
                        self.pos.x = x as f32 * TILE as f32 - self.width - 0.01;
                    } else if self.vel.x < 0.0 {
                        self.pos.x = (x + 1) as f32 * TILE as f32 + 0.01;
                    }
                    self.vel.x = 0.0;
                    return;
                }
            }
        }
    }

    fn resolve_y(&mut self, world: &World) {
        let prev_bottom = self.pos.y + self.height - self.vel.y * 0.0;
        let x0 = (self.pos.x / TILE as f32).floor() as i32;
        let x1 = ((self.pos.x + self.width) / TILE as f32).floor() as i32;
        let y0 = (self.pos.y / TILE as f32).floor() as i32;
        let y1 = ((self.pos.y + self.height) / TILE as f32).floor() as i32;
        self.on_ground = false;
        for y in y0..=y1 {
            for x in x0..=x1 {
                let t = world.get(x, y);
                let solid = crate::world::is_solid(t);
                let plat = t == crate::world::PLATFORM;
                if solid || (plat && self.vel.y >= 0.0) {
                    if self.vel.y > 0.0 {
                        if plat {
                            let top = y as f32 * TILE as f32;
                            if prev_bottom > top + 3.0 + self.vel.y * 0.0 {
                                continue;
                            }
                        }
                        self.pos.y = y as f32 * TILE as f32 - self.height - 0.01;
                        self.vel.y = 0.0;
                        self.on_ground = true;
                        return;
                    } else if self.vel.y < 0.0 && solid {
                        self.pos.y = (y + 1) as f32 * TILE as f32 + 0.01;
                        self.vel.y = 0.0;
                        return;
                    }
                }
            }
        }
        // Platform check: support only from above.
        if self.vel.y >= 0.0 {
            let feet_y = self.pos.y + self.height;
            let ty = (feet_y / TILE as f32).floor() as i32;
            for x in x0..=x1 {
                if world.get(x, ty) == crate::world::PLATFORM {
                    let top = ty as f32 * TILE as f32;
                    if feet_y >= top - 0.5 && feet_y <= top + 2.5 {
                        self.pos.y = top - self.height - 0.01;
                        self.vel.y = 0.0;
                        self.on_ground = true;
                        return;
                    }
                }
            }
        }
    }

    pub fn intersects_tile(&self, tx: i32, ty: i32) -> bool {
        let x = tx as f32 * TILE as f32;
        let y = ty as f32 * TILE as f32;
        self.pos.x < x + TILE as f32
            && self.pos.x + self.width > x
            && self.pos.y < y + TILE as f32
            && self.pos.y + self.height > y
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::input::Input;
    use crate::world;

    #[test]
    fn player_falls_and_lands() {
        let mut w = world::generate(42);
        // A flat test platform.
        for x in 100..130 {
            for y in 100..104 {
                w.set_tile(x, y, world::STONE);
            }
            for y in 90..100 {
                w.set_tile(x, y, world::AIR);
            }
        }
        let mut p = Player::new(V2::new(108.0 * 16.0, 92.0 * 16.0));
        let input = Input::new();
        for _ in 0..240 {
            p.update(&w, &input, 1.0 / 60.0);
        }
        assert!(p.on_ground, "player should land");
        assert!(p.pos.y + p.height <= 100.0 * 16.0 + 1.0);
    }

    #[test]
    fn player_jumps() {
        let mut w = world::generate(42);
        for x in 100..130 {
            for y in 100..104 {
                w.set_tile(x, y, world::STONE);
            }
            for y in 88..100 {
                w.set_tile(x, y, world::AIR);
            }
        }
        let mut p = Player::new(V2::new(108.0 * 16.0, 98.0 * 16.0));
        let mut input = Input::new();
        for _ in 0..30 {
            p.update(&w, &input, 1.0 / 60.0);
        }
        input.keys[crate::input::KEY_SPACE] = true;
        input.pressed[crate::input::KEY_SPACE] = true;
        p.update(&w, &input, 1.0 / 60.0);
        assert!(p.vel.y < 0.0);
    }
}

