        let player = Player::new(world.spawn);
        let mut game = Game {
            world,
            player,
            inventory: Inventory::new(),
            enemies: Vec::new(),
            drops: Vec::new(),
            bombs: Vec::new(),
            particles: Vec::new(),
            texts: Vec::new(),
            toasts: Vec::new(),
            banner: None,
            mode: Mode::Attract,
            inv_open: false,
            map_open: false,
            show_help: false,
            view,
            camera: V2::ZERO,
            shake: 0.0,
            flash: 0.0,
            flash_color: 0xFFFFFF80,
            time: 0.28,
            day: 1,
            mining: None,
            swing_hit: false,
            boss_active: false,
            boss_defeated: false,
            victory_timer: 0.0,
            death_timer: 0.0,
            flags: QuestFlags::default(),
            stats: Stats::default(),
            regen_timer: 0.0,
            spawn_timer: 4.0,
            ambient_timer: 0.0,
            music_mode: 0,
            title_phase: 0.0,
            seed,
            rng: Rng::new(seed ^ 0xABCD_1234),
            touch_mode: false,
