fn menu_backdrop(game: &Game, tint: u32) {
    gfx::rect(0.0, 0.0, game.view.x, game.view.y, tint);
}

fn draw_pause(game: &Game) {
    let l = pause_layout(game);
    let s = l.s;
    menu_backdrop(game, rgba(4, 6, 12, 185));
    shadow_panel(l.panel, rgba(18, 22, 32, 248), rgb(112, 142, 150));
    gfx::text("PAUSED", l.panel.x + 16.0 * s, l.panel.y + 22.0 * s, 15.0 * s, rgb(240, 234, 220), 0, 900);
    gfx::text("The world waits.", l.panel.x + 16.0 * s, l.panel.y + 36.0 * s, 5.2 * s, rgba(170, 182, 192, 220), 0, 500);

    let (obj, sub) = game.objective();
    gfx::rect(l.panel.x + 15.0 * s, l.panel.y + 46.0 * s, l.panel.w - 30.0 * s, 28.0 * s, rgba(32, 38, 48, 190));
    gfx::text("OBJECTIVE", l.panel.x + 21.0 * s, l.panel.y + 53.0 * s, 4.5 * s, rgb(214, 182, 104), 0, 800);
    gfx::text(obj, l.panel.x + 21.0 * s, l.panel.y + 63.0 * s, 6.2 * s, rgb(238, 234, 222), 0, 700);
    gfx::text(sub, l.panel.x + 21.0 * s, l.panel.y + 71.0 * s, 4.3 * s, rgba(172, 182, 192, 210), 0, 500);

    if game.show_help {
        let lines = [
            "A / D or arrows   Move",
            "Space / W        Jump (swim in water)",
            "Left click       Mine, attack or place",
            "Right click      Place selected block",
            "1-0 / wheel      Select hotbar",
            "E / C            Inventory & crafting",
            "M                World map",
            "Esc              Pause",
            "N                Mute sound",
        ];
        for (i, line) in lines.iter().enumerate() {
            gfx::text(line, l.panel.x + 18.0 * s, l.panel.y + (88.0 + i as f32 * 9.0) * s, 4.7 * s, rgba(198, 206, 214, 230), 0, 500);
        }
    } else {
        let stats = format!(
            "Mined {}   Placed {}   Slain {}   Deaths {}   Played {}",
            game.stats.blocks_mined,
            game.stats.blocks_placed,
            game.stats.enemies_killed,
            game.stats.deaths,
            format_time(game.stats.play_time)
        );
        gfx::text(&stats, l.panel.x + 18.0 * s, l.panel.y + 100.0 * s, 4.6 * s, rgba(186, 196, 204, 220), 0, 500);
        let tip = if game.boss_defeated {
            "The crown is yours. The world is yours."
        } else {
            "Tip: torches, platforms and a workbench make every trip easier."
        };
        gfx::text(tip, l.panel.x + 18.0 * s, l.panel.y + 112.0 * s, 4.4 * s, rgba(160, 176, 184, 200), 0, 500);
    }

    button(game, l.resume, "Resume");
    button(game, l.help, if game.show_help { "Hide Controls" } else { "Controls" });
    button(game, l.mute, if game.muted { "Sound: Off" } else { "Sound: On" });
    button(game, l.quit, "Save & Quit to Title");
}

fn button(game: &Game, r: Rect, label: &str) {
    let hover = r.contains(game.mouse_screen);
    let fill = if hover { rgba(62, 88, 90, 245) } else { rgba(34, 42, 54, 235) };
    gfx::rect(r.x, r.y, r.w, r.h, fill);
    stroke_rect(r, 1.2, if hover { rgb(232, 198, 110) } else { rgba(104, 124, 136, 200) });
    gfx::text(label, r.center().x, r.center().y, 6.2 * ui_scale(game), if hover { rgb(246, 240, 222) } else { rgb(214, 216, 214) }, 1, 700);
}

fn draw_death(game: &Game) {
    let l = death_layout(game);
    let s = l.s;
    menu_backdrop(game, rgba(28, 4, 8, 200));
    shadow_panel(l.panel, rgba(26, 16, 20, 250), rgb(150, 70, 78));
    gfx::text("YOU DIED", l.panel.x + l.panel.w * 0.5, l.panel.y + 34.0 * s, 18.0 * s, rgb(236, 96, 96), 1, 900);
    gfx::text("The world is unkind.", l.panel.x + l.panel.w * 0.5, l.panel.y + 50.0 * s, 5.8 * s, rgba(218, 190, 190, 220), 1, 500);
    let line = format!("Slain {}   Mined {}   Deaths {}", game.stats.enemies_killed, game.stats.blocks_mined, game.stats.deaths);
    gfx::text(&line, l.panel.x + l.panel.w * 0.5, l.panel.y + 68.0 * s, 4.8 * s, rgba(188, 176, 176, 210), 1, 500);
    gfx::text("Your gear is safe. The world is not.", l.panel.x + l.panel.w * 0.5, l.panel.y + 82.0 * s, 4.5 * s, rgba(170, 160, 164, 200), 1, 500);
    button(game, l.respawn, "Respawn");
    button(game, l.quit, "Save & Quit to Title");
    gfx::text("Space or Enter also respawns", l.panel.x + l.panel.w * 0.5, l.panel.y + l.panel.h - 4.0 * s, 3.8 * s, rgba(160, 152, 156, 170), 1, 500);
}

fn draw_victory(game: &Game) {
    let l = victory_layout(game);
    let s = l.s;
    menu_backdrop(game, rgba(8, 8, 4, 195));
    shadow_panel(l.panel, rgba(26, 24, 16, 250), rgb(210, 172, 76));
    gfx::text("THE KING IS DEAD", l.panel.x + l.panel.w * 0.5, l.panel.y + 30.0 * s, 15.0 * s, rgb(255, 216, 104), 1, 900);
    gfx::text("The Slime King has fallen.", l.panel.x + l.panel.w * 0.5, l.panel.y + 47.0 * s, 6.2 * s, rgb(238, 228, 198), 1, 600);
    let line = format!(
        "Slain {}   Mined {}   Deaths {}   Time {}",
        game.stats.enemies_killed,
        game.stats.blocks_mined,
        game.stats.deaths,
        format_time(game.stats.play_time)
    );
    gfx::text(&line, l.panel.x + l.panel.w * 0.5, l.panel.y + 65.0 * s, 4.8 * s, rgba(212, 202, 178, 220), 1, 500);
    gfx::text("The crown is yours. The world is not finished.", l.panel.x + l.panel.w * 0.5, l.panel.y + 78.0 * s, 4.8 * s, rgba(196, 186, 160, 210), 1, 500);
    button(game, l.continue_btn, "Continue Exploring");
    button(game, l.quit, "Save & Quit to Title");
}

fn format_time(secs: f32) -> String {
    let m = (secs / 60.0).floor() as i32;
    let s = (secs as i32) % 60;
    if m >= 60 {
        format!("{}h {:02}m", m / 60, m % 60)
    } else {
        format!("{}m {:02}s", m, s)
    }
}

//! WebAssembly entry points for Terraforge.
//!
//! The browser owns the canvas; Rust owns the entire simulation and draws via
//! a tiny immediate-mode bridge.

mod entities;
mod game;
mod gfx;
mod input;
mod items;
mod math;
mod physics;
mod player;
mod render;
mod rng;
mod ui;
mod world;

use std::cell::RefCell;
use game::Game;
use input::Input;
use math::V2;

thread_local! {
    static GAME: RefCell<Option<Game>> = RefCell::new(None);
    static INPUT: RefCell<Input> = RefCell::new(Input::new());
    static DEBUG: RefCell<Vec<u8>> = RefCell::new(Vec::new());
}

fn with_game<R>(f: impl FnOnce(&mut Game) -> R) -> Option<R> {
    GAME.with(|g| g.borrow_mut().as_mut().map(f))
}

fn with_input<R>(f: impl FnOnce(&mut Input) -> R) -> R {
    INPUT.with(|i| f(&mut i.borrow_mut()))
}

#[no_mangle]
pub extern "C" fn game_init(view_w: f32, view_h: f32, seed: u32) {
    let view = V2::new(view_w.max(200.0), view_h.max(200.0));
    let game = Game::new(view, seed);
    gfx::minimap(game.world.minimap.as_ptr(), world::W as u32, world::H as u32);
    GAME.with(|g| *g.borrow_mut() = Some(game));
    INPUT.with(|i| *i.borrow_mut() = Input::new());
}

#[no_mangle]
pub extern "C" fn game_resize(view_w: f32, view_h: f32) {
    with_game(|g| g.resize(V2::new(view_w.max(200.0), view_h.max(200.0))));
}

#[no_mangle]
pub extern "C" fn game_tick(dt: f32) {
    with_input(|input| {
        with_game(|g| {
            g.update(dt, input);
            g.render();
        });
        input.end_frame();
    });
}

#[no_mangle]
pub extern "C" fn game_key(key: u32, down: u32) {
    let k = key as usize;
    if k >= input::KEY_COUNT {
        return;
    }
    with_input(|i| {
        let was = i.keys[k];
        i.keys[k] = down != 0;
        if down != 0 && !was {
            i.pressed[k] = true;
        }
        i.any_input = true;
    });
}

#[no_mangle]
pub extern "C" fn game_pointer_move(x: f32, y: f32) {
    with_input(|i| {
        i.mouse = V2::new(x, y);
        i.any_input = true;
    });
}

#[no_mangle]
pub extern "C" fn game_pointer_down(button: u32) {
    with_input(|i| {
        if button == 0 {
            i.mouse_down = true;
            i.mouse_pressed = true;
        } else if button == 2 || button == 1 {
            i.right_down = true;
            i.right_pressed = true;
        }
        i.any_input = true;
    });
}

#[no_mangle]
pub extern "C" fn game_pointer_up(button: u32) {
    with_input(|i| {
        if button == 0 {
            i.mouse_down = false;
            i.mouse_released = true;
        } else if button == 2 || button == 1 {
            i.right_down = false;
            i.right_released = true;
        }
        i.any_input = true;
    });
}

#[no_mangle]
pub extern "C" fn game_wheel(delta: f32) {
    with_input(|i| i.wheel += delta);
}

#[no_mangle]
pub extern "C" fn game_set_touch_mode(touch: u32) {
    with_game(|g| g.set_touch_mode(touch != 0));
    with_input(|i| i.touch_mode = touch != 0);
}

#[no_mangle]
pub extern "C" fn game_play() {
    with_game(|g| g.play());
}

#[no_mangle]
pub extern "C" fn game_new_world(seed: u32) {
    with_game(|g| g.new_world(seed));
}

#[no_mangle]
pub extern "C" fn game_has_save() -> u32 {
    with_game(|g| g.has_save as u32).unwrap_or(0)
}

#[no_mangle]
pub extern "C" fn game_toggle_inventory() {
    with_game(|g| g.toggle_inventory());
}

#[no_mangle]
pub extern "C" fn game_toggle_map() {
    with_game(|g| g.toggle_map());
}

#[no_mangle]
pub extern "C" fn game_toggle_pause() {
    with_game(|g| g.toggle_pause());
}

#[no_mangle]
pub extern "C" fn game_toggle_place() {
    with_game(|g| g.toggle_place());
}

#[no_mangle]
pub extern "C" fn game_toggle_mute() {
    with_game(|g| g.toggle_mute());
}

#[no_mangle]
pub extern "C" fn game_save() {
    with_game(|g| g.save_game());
}

// ---------------------------------------------------------------------------
// Debug / verification helpers. These are harmless in normal play.
// ---------------------------------------------------------------------------

#[no_mangle]
pub extern "C" fn game_debug_state() -> u32 {
    let json = with_game(|g| g.debug_json()).unwrap_or_else(|| "{}".to_string());
    DEBUG.with(|d| {
        let mut d = d.borrow_mut();
        *d = json.into_bytes();
        d.len() as u32
    })
}

#[no_mangle]
pub extern "C" fn game_debug_ptr() -> *const u8 {
    DEBUG.with(|d| d.borrow().as_ptr())
}

#[no_mangle]
pub extern "C" fn game_debug_give(item: u32, count: u32) {
    with_game(|g| {
        if let Some(id) = items::ItemId::from_u8(item as u8) {
            g.inventory.add(id, count);
        }
    });
}

#[no_mangle]
pub extern "C" fn game_debug_teleport(x: f32, y: f32) {
    with_game(|g| {
        g.player.pos = V2::new(x, y);
        g.player.vel = V2::ZERO;
        g.player.respawn = g.player.pos;
        g.center_camera();
    });
}

#[no_mangle]
pub extern "C" fn game_debug_time(t: f32) {
    with_game(|g| g.time = t.rem_euclid(1.0));
}

#[no_mangle]
pub extern "C" fn game_debug_heal() {
    with_game(|g| {
        g.player.hp = g.player.max_hp;
        g.player.dead = false;
    });
}

#[no_mangle]
pub extern "C" fn game_debug_spawn_boss() {
    with_game(|g| {
        g.inventory.add(items::ItemId::Crown, 1);
        g.flags.summoned_boss = true;
        g.boss_active = true;
        let pc = g.player.center();
        g.enemies.push(entities::Enemy::new(
            entities::EnemyKind::KingSlime,
            V2::new(pc.x + 120.0, pc.y - 80.0),
        ));
    });
}

#[no_mangle]
pub extern "C" fn game_debug_kill_boss() {
    with_game(|g| {
        for i in 0..g.enemies.len() {
            if g.enemies[i].kind.is_boss() && !g.enemies[i].dead {
                g.enemies[i].hp = 0.0;
                g.enemies[i].dead = true;
                g.boss_active = false;
                g.boss_defeated = true;
                g.flags.boss_defeated = true;
                g.victory_timer = 0.2;
            }
        }
    });
}

#[no_mangle]
pub extern "C" fn game_debug_craft(index: u32) {
    with_game(|g| g.craft(index as usize));
}

:root {
  --ink: #e9ecf1;
  --muted: #9aa6b2;
  --gold: #e8c060;
  --green: #7ddba8;
  --panel: rgba(11, 16, 24, 0.78);
  --line: rgba(220, 235, 245, 0.12);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #05070c;
  color: var(--ink);
  font-family: "Trebuchet MS", "Segoe UI", system-ui, -apple-system, sans-serif;
  -webkit-font-smoothing: antialiased;
  overscroll-behavior: none;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: crosshair;
  background: #0a0e18;
}

/* ---------------------------------------------------------------- title */
.overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: max(18px, env(safe-area-inset-top)) max(18px, env(safe-area-inset-right)) max(18px, env(safe-area-inset-bottom)) max(18px, env(safe-area-inset-left));
  background:
    radial-gradient(120% 90% at 50% 12%, rgba(13, 30, 34, 0.10), rgba(3, 5, 10, 0.78) 68%),
    linear-gradient(180deg, rgba(4, 6, 12, 0.52), rgba(4, 6, 12, 0.84));
  z-index: 20;
  transition: opacity 220ms ease;
}

.overlay.hidden { display: none; }

.title-card {
  position: relative;
  width: min(760px, 100%);
  max-height: 100%;
  overflow: auto;
  padding: clamp(22px, 4.4vw, 48px) clamp(20px, 5vw, 58px);
  border: 1px solid var(--line);
  border-radius: 18px;
  background:
    radial-gradient(110% 90% at 15% 0%, rgba(120, 180, 150, 0.10), transparent 55%),
    radial-gradient(90% 80% at 95% 100%, rgba(232, 192, 96, 0.08), transparent 55%),
    linear-gradient(160deg, rgba(15, 22, 30, 0.88), rgba(7, 11, 18, 0.92));
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.65), inset 0 1px 0 rgba(255, 255, 255, 0.05);
  backdrop-filter: blur(7px);
  scrollbar-width: thin;
}

.title-card::before {
  content: "";
  position: absolute;
  left: 10%;
  right: 10%;
  top: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(232, 192, 96, 0.65), transparent);
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 11px;
  letter-spacing: 0.32em;
  color: #a9b7b2;
  font-weight: 700;
}

.dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 14px var(--green);
}

.logo {
  margin: 12px 0 2px;
  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(54px, 12vw, 116px);
  line-height: 0.9;
  letter-spacing: 0.015em;
  font-weight: 900;
  color: #f2ead9;
  text-shadow: 0 4px 26px rgba(0, 0, 0, 0.55), 0 1px 0 rgba(255, 255, 255, 0.18);
}

.logo span {
  background: linear-gradient(180deg, #ffe6a0 0%, #e8b54a 48%, #a86f22 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 3px 14px rgba(232, 181, 74, 0.22));
}

.tagline {
  margin: 10px 0 0;
  font-size: clamp(14px, 2vw, 18px);
  color: #b9c4c6;
  letter-spacing: 0.06em;
}

.title-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 24px;
}

.btn {
  appearance: none;
  border: 1px solid transparent;
  border-radius: 10px;
  padding: 13px 30px;
  font: inherit;
  font-size: 17px;
  font-weight: 800;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  cursor: pointer;
  transition: transform 120ms ease, box-shadow 160ms ease, background 160ms ease;
  touch-action: manipulation;
}

.btn:hover { transform: translateY(-1px); }
.btn:active { transform: translateY(1px); }

.btn.primary {
  color: #102016;
  background: linear-gradient(180deg, #f2d27c 0%, #d9a93f 55%, #b9842a 100%);
  border-color: rgba(255, 245, 210, 0.5);
  box-shadow: 0 8px 30px rgba(217, 169, 63, 0.28), inset 0 1px 0 rgba(255, 255, 255, 0.55);
}

.btn.primary:hover { box-shadow: 0 10px 38px rgba(217, 169, 63, 0.42), inset 0 1px 0 rgba(255, 255, 255, 0.65); }

.btn.ghost {
  color: #d9e2e4;
  background: rgba(255, 255, 255, 0.045);
  border-color: rgba(220, 235, 245, 0.16);
}

.btn.ghost:hover { background: rgba(255, 255, 255, 0.09); }

.save-note {
  margin: 12px 0 0;
  font-size: 13px;
  color: #9fd7b8;
  letter-spacing: 0.03em;
}

.control-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px 26px;
  margin-top: 26px;
  padding-top: 22px;
  border-top: 1px solid var(--line);
  color: #aab5bc;
  font-size: 13px;
}

.control-grid div {
  display: flex;
  align-items: center;
  gap: 7px;
  min-height: 28px;
}

kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 25px;
  height: 23px;
  padding: 0 6px;
  border-radius: 5px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-bottom-color: rgba(0, 0, 0, 0.5);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.10), rgba(255, 255, 255, 0.035));
  color: #dde6e8;
  font-family: ui-monospace, "SFMono-Regular", Menlo, monospace;
  font-size: 11px;
  font-weight: 700;
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.06);
}

.feature-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  margin-top: 20px;
  color: #7f8f93;
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.feature-row i {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: #5a6a6e;
}

.footnote {
  margin: 14px 0 0;
  color: #637077;
  font-size: 11px;
  letter-spacing: 0.05em;
}

/* --------------------------------------------------------------- loading */
#loading {
  position: absolute;
  inset: 0;
  z-index: 30;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  background: #05070c;
  color: #8fa0a8;
  font-size: 13px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  transition: opacity 260ms ease;
}

#loading.hidden { opacity: 0; pointer-events: none; }

.spinner {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 2px solid rgba(232, 192, 96, 0.18);
  border-top-color: var(--gold);
  animation: spin 900ms linear infinite;
}

@keyframes spin { to { transform: rotate(360deg); } }

#error {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  z-index: 40;
  max-width: min(560px, 90vw);
  padding: 20px 24px;
  border: 1px solid rgba(230, 100, 100, 0.35);
  border-radius: 12px;
  background: rgba(28, 10, 12, 0.96);
  color: #ffb8b8;
  font-size: 14px;
  line-height: 1.5;
  white-space: pre-wrap;
}

/* ------------------------------------------------------------ touch UI */
#touch {
  position: absolute;
  inset: 0;
  z-index: 15;
  display: none;
  pointer-events: none;
  user-select: none;
  -webkit-user-select: none;
}

body.touch #touch { display: block; }
body.title-open #touch { display: none; }

#touch button {
  pointer-events: auto;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
  appearance: none;
  color: #e8eeea;
  font-family: inherit;
  border: 1px solid rgba(220, 240, 235, 0.24);
  background: radial-gradient(80% 80% at 50% 20%, rgba(70, 96, 92, 0.58), rgba(10, 16, 20, 0.62));
  box-shadow: 0 4px 18px rgba(0, 0, 0, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.12);
  backdrop-filter: blur(4px);
}

#touch button:active,
#touch button.on {
  background: radial-gradient(80% 80% at 50% 20%, rgba(140, 190, 160, 0.72), rgba(30, 56, 48, 0.7));
  border-color: rgba(232, 220, 150, 0.55);
  transform: scale(0.96);
}

.touch-utility {
  position: absolute;
  top: max(10px, env(safe-area-inset-top));
  right: max(10px, env(safe-area-inset-right));
  display: flex;
  gap: 8px;
}

.touch-utility button {
  width: 42px;
  height: 42px;
  border-radius: 12px;
  font-size: 20px;
  line-height: 1;
}

.touch-move {
  position: absolute;
  left: max(14px, env(safe-area-inset-left));
  bottom: max(16px, env(safe-area-inset-bottom));
  display: flex;
  gap: 12px;
}

.touch-move button {
  width: 66px;
  height: 66px;
  border-radius: 18px;
  font-size: 26px;
}

.touch-action {
  position: absolute;
  right: max(14px, env(safe-area-inset-right));
  bottom: max(16px, env(safe-area-inset-bottom));
  display: flex;
  align-items: flex-end;
  gap: 12px;
}

.touch-action button {
  width: 66px;
  height: 66px;
  border-radius: 50%;
  font-size: 25px;
}

#m-jump {
  width: 78px;
  height: 78px;
  border-radius: 50%;
  font-size: 30px;
  border-color: rgba(232, 192, 96, 0.35);
  background: radial-gradient(80% 80% at 50% 20%, rgba(132, 110, 62, 0.62), rgba(24, 22, 14, 0.66));
}

#m-place { border-radius: 16px; font-size: 20px; }

@media (max-height: 620px) {
  .control-grid { margin-top: 15px; padding-top: 14px; gap: 4px 20px; font-size: 11px; }
  .feature-row, .footnote { display: none; }
  .title-actions { margin-top: 14px; }
  .tagline { margin-top: 5px; }
}

@media (max-width: 560px) {
  .overlay { padding: max(10px, env(safe-area-inset-top)) 10px max(10px, env(safe-area-inset-bottom)); align-items: flex-start; }
  .title-card { margin-top: max(12px, env(safe-area-inset-top)); padding: 22px 20px; border-radius: 15px; }
  .logo { font-size: clamp(46px, 15.5vw, 72px); }
  .control-grid { grid-template-columns: 1fr 1fr; gap: 6px 14px; font-size: 11.5px; }
  .btn { flex: 1 1 auto; padding: 13px 18px; font-size: 15px; }
  .title-actions { gap: 9px; }
  .feature-row { display: none; }
  .footnote { font-size: 10px; }
}

@media (pointer: fine) {
  body.touch #touch { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  * { animation-duration: 0.001ms !important; transition-duration: 0.001ms !important; }
}

