23: #[inline]
24: pub fn mix(a: u32, b: u32, t: f32) -> u32 {
25:     let t = crate::math::clamp(t, 0.0, 1.0);
26:     let ar = (a >> 24) as f32;
27:     let ag = ((a >> 16) & 255) as f32;
28:     let ab = ((a >> 8) & 255) as f32;
29:     let aa = (a & 255) as f32;
30:     let br = (b >> 24) as f32;
31:     let bg = ((b >> 16) & 255) as f32;
32:     let bb = ((b >> 8) & 255) as f32;
33:     let ba = (b & 255) as f32;
34:     rgba(
35:         (ar + (br - ar) * t) as u8,
36:         (ag + (bg - ag) * t) as u8,
37:         (ab + (bb - ab) * t) as u8,
38:         (aa + (ba - aa) * t) as u8,
39:     )
40: }
