    pub minimap: Vec<u8>,
    pub map_dirty: bool,
}

impl World {
    #[inline]
    pub fn idx(x: i32, y: i32) -> usize {
        (y * W + x) as usize
    }

    #[inline]
    pub fn in_bounds(x: i32, y: i32) -> bool {
        let y = ground - i;
        if !World::in_bounds(x, y) {
            return;
        }
        set_t(tiles, x, y, WOOD);
    }
    let top = ground - height;
    if pine {
        for layer in 0..4 {
            let y = top - layer;
            let r = 2 + (3 - layer) as i32;
